package com.midnight.music;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.os.Bundle;
import android.provider.Settings;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

public class MainActivity extends Activity {
    private ApiClient api; private LinearLayout root,content; private EditText search; private TextView status,now; private Button playBtn;
    private final ArrayList<JSONObject> tracks=new ArrayList<>(),visible=new ArrayList<>(); private JSONArray albums=new JSONArray(),artists=new JSONArray(); private String mode="tracks"; private BroadcastReceiver receiver;
    private final int PICK_AUDIO=44;
    private int bg=Color.rgb(8,14,26),panel=Color.rgb(17,29,48),blue=Color.rgb(148,189,255),text=Color.rgb(242,246,255),muted=Color.rgb(166,181,205);

    @Override public void onCreate(Bundle b){super.onCreate(b);api=new ApiClient(this);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);if(android.os.Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},7);receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){now.setText(i.getStringExtra("title")+"\n"+i.getStringExtra("artist"));playBtn.setText(i.getBooleanExtra("playing",false)?"❚❚":"▶");}};registerReceiver(receiver,new IntentFilter(PlaybackService.ACTION_STATE),android.os.Build.VERSION.SDK_INT>=33?Context.RECEIVER_NOT_EXPORTED:0);if(api.hasSession())checkSession();else loginScreen();}
    private TextView tv(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextColor(text);v.setTextSize(sp);v.setPadding(dp(12),dp(10),dp(12),dp(10));return v;}
    private Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(Color.rgb(8,20,36));b.setBackgroundColor(blue);b.setAllCaps(false);return b;}
    private EditText edit(String hint){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(muted);e.setTextColor(text);e.setSingleLine();e.setBackgroundColor(Color.rgb(20,33,57));e.setPadding(dp(14),dp(10),dp(14),dp(10));return e;}
    private void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);root.setPadding(dp(16),dp(14),dp(16),dp(12));setContentView(root);}
    private void loginScreen(){base();TextView logo=tv("◉ Midnight",30);logo.setTypeface(null,1);root.addView(logo);TextView sub=tv("Вход в твою музыкальную библиотеку",15);sub.setTextColor(muted);root.addView(sub);EditText server=edit("Адрес сервера");server.setText(api.base());root.addView(server,lp(-1,-2,0,10));EditText user=edit("Логин");root.addView(user,lp(-1,-2,0,10));EditText pass=edit("Пароль");pass.setInputType(0x00000081);root.addView(pass,lp(-1,-2,0,12));status=tv("",13);status.setTextColor(Color.rgb(255,180,180));root.addView(status);Button login=btn("Войти");root.addView(login,lp(-1,dp(50),0,10));login.setOnClickListener(v->{login.setEnabled(false);status.setText("Вход…");new Thread(()->{try{api.login(server.getText().toString(),user.getText().toString(),pass.getText().toString());runOnUiThread(this::libraryScreen);}catch(Exception e){runOnUiThread(()->{status.setText(e.getMessage());login.setEnabled(true);});}}).start();});}
    private void checkSession(){new Thread(()->{try{api.me();runOnUiThread(this::libraryScreen);}catch(Exception e){api.clear();runOnUiThread(this::loginScreen);}}).start();}
    private void libraryScreen(){base();LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);TextView logo=tv("◉ Midnight",24);logo.setTypeface(null,1);top.addView(logo,new LinearLayout.LayoutParams(0,-2,1));Button upload=btn("＋");upload.setContentDescription("Добавить музыку");upload.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK_AUDIO);});top.addView(upload,new LinearLayout.LayoutParams(dp(58),dp(48)));root.addView(top);
        search=edit("Найти трек или исполнителя");search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){renderList();}public void afterTextChanged(android.text.Editable e){}});root.addView(search,lp(-1,dp(48),0,10));
        LinearLayout tabs=new LinearLayout(this);tabs.setGravity(Gravity.CENTER);for(String[] x:new String[][]{{"Музыка","tracks"},{"Альбомы","albums"},{"Исполнители","artists"}}){Button b=btn(x[0]);b.setTag(x[1]);b.setOnClickListener(v->{mode=(String)v.getTag();renderList();});tabs.addView(b,new LinearLayout.LayoutParams(0,dp(48),1));}root.addView(tabs,lp(-1,-2,0,8));
        status=tv("Загрузка…",13);status.setTextColor(muted);root.addView(status);ScrollView sc=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout mini=new LinearLayout(this);mini.setGravity(Gravity.CENTER_VERTICAL);mini.setPadding(dp(8),dp(8),dp(8),dp(8));mini.setBackgroundColor(panel);now=tv("Ничего не играет",14);mini.addView(now,new LinearLayout.LayoutParams(0,-2,1));Button prev=btn("◀");playBtn=btn("▶");Button next=btn("▶| ");prev.setOnClickListener(v->service(PlaybackService.PREV));playBtn.setOnClickListener(v->service(PlaybackService.TOGGLE));next.setOnClickListener(v->service(PlaybackService.NEXT));mini.addView(prev,new LinearLayout.LayoutParams(dp(56),dp(48)));mini.addView(playBtn,new LinearLayout.LayoutParams(dp(56),dp(48)));mini.addView(next,new LinearLayout.LayoutParams(dp(56),dp(48)));root.addView(mini);
        TextView logout=tv("Выйти",13);logout.setTextColor(muted);logout.setGravity(Gravity.CENTER);logout.setOnClickListener(v->{api.clear();loginScreen();});root.addView(logout);loadLibrary();}
    private void loadLibrary(){status.setText("Обновление медиатеки…");new Thread(()->{try{JSONObject l=api.library();JSONArray own=l.optJSONArray("tracks"),shared=l.optJSONArray("sharedTracks");tracks.clear();for(JSONArray a:new JSONArray[]{own,shared})if(a!=null)for(int i=0;i<a.length();i++){JSONObject t=a.getJSONObject(i);t.put("stream",api.absolute(t.optString("stream")));tracks.add(t);}albums=l.optJSONArray("albums")==null?new JSONArray():l.optJSONArray("albums");artists=l.optJSONArray("artists")==null?new JSONArray():l.optJSONArray("artists");runOnUiThread(()->{status.setText(tracks.size()+" треков");renderList();});}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}).start();}
    private void renderList(){if(content==null)return;content.removeAllViews();String q=search==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT);if(mode.equals("tracks")){visible.clear();for(JSONObject t:tracks){String hay=(t.optString("title")+" "+t.optString("artist")+" "+t.optString("album")).toLowerCase(Locale.ROOT);if(q.isEmpty()||hay.contains(q))visible.add(t);}for(int i=0;i<visible.size();i++){int index=i;JSONObject t=visible.get(i);TextView row=row(t.optString("title"),t.optString("artist")+(t.optString("album").isBlank()?"":" · "+t.optString("album"))+(t.optBoolean("readOnly")?" · PUBLIC":""));row.setOnClickListener(v->play(index));content.addView(row);}if(visible.isEmpty())content.addView(empty("Ничего не найдено"));}
        else if(mode.equals("albums")){for(int i=0;i<albums.length();i++){JSONObject a=albums.optJSONObject(i);if(a==null)continue;String hay=(a.optString("name")+" "+a.optString("artist")).toLowerCase(Locale.ROOT);if(!q.isEmpty()&&!hay.contains(q))continue;TextView row=row(a.optString("name"),a.optString("artist")+" · "+a.optInt("trackCount")+" треков · "+(a.optBoolean("isOwner",true)?(a.optString("visibility").equals("public")?"Публичный":"Личный"):"Публичный @"+a.optString("ownerName")));String id=a.optString("id");row.setOnClickListener(v->showEntityTracks("albumId",id));content.addView(row);}}
        else {for(int i=0;i<artists.length();i++){JSONObject a=artists.optJSONObject(i);if(a==null)continue;String hay=a.optString("name").toLowerCase(Locale.ROOT);if(!q.isEmpty()&&!hay.contains(q))continue;TextView row=row(a.optString("name"),a.optInt("trackCount")+" треков · "+(a.optBoolean("isOwner",true)?(a.optString("visibility").equals("public")?"Публичная группа":"Личная группа"):"Публичная @"+a.optString("ownerName")));String id=a.optString("id");row.setOnClickListener(v->showEntityTracks("artistId",id));content.addView(row);}}}
    private void showEntityTracks(String key,String id){mode="tracks";search.setText("");visible.clear();for(JSONObject t:tracks)if(id.equals(t.optString(key)))visible.add(t);content.removeAllViews();for(int i=0;i<visible.size();i++){int idx=i;JSONObject t=visible.get(i);TextView row=row(t.optString("title"),t.optString("artist")+" · "+t.optString("album"));row.setOnClickListener(v->play(idx));content.addView(row);}status.setText(visible.size()+" треков");}
    private TextView row(String title,String sub){TextView r=tv(title+"\n"+sub,16);r.setBackgroundColor(panel);r.setPadding(dp(14),dp(14),dp(14),dp(14));r.setTextColor(text);LinearLayout.LayoutParams p=lp(-1,-2,0,8);r.setLayoutParams(p);return r;}
    private TextView empty(String s){TextView t=tv(s,17);t.setGravity(Gravity.CENTER);t.setTextColor(muted);return t;}
    private void play(int idx){if(idx<0||idx>=visible.size())return;JSONArray q=new JSONArray();for(JSONObject t:visible){JSONObject x=new JSONObject();try{x.put("id",t.optString("id")).put("title",t.optString("title")).put("artist",t.optString("artist")).put("stream",t.optString("stream"));}catch(Exception ignored){}q.put(x);}Intent i=new Intent(this,PlaybackService.class).setAction(PlaybackService.PLAY).putExtra("queue",q.toString()).putExtra("index",idx).putExtra("cookie",api.cookie());startForegroundService(i);}
    private void service(String action){startService(new Intent(this,PlaybackService.class).setAction(action));}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_AUDIO&&result==RESULT_OK&&data!=null&&data.getData()!=null){Uri u=data.getData();status.setText("Загрузка файла…");new Thread(()->{try{api.upload(u);runOnUiThread(()->{status.setText("Файл добавлен");loadLibrary();});}catch(Exception e){runOnUiThread(()->status.setText(e.getMessage()));}}).start();}}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private LinearLayout.LayoutParams lp(int w,int h,int bottom,int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(w,h);p.bottomMargin=dp(bottom);p.topMargin=dp(top);return p;}
    @Override protected void onDestroy(){try{unregisterReceiver(receiver);}catch(Exception ignored){}super.onDestroy();}
}
